    ('96e78e9b', 'What caused the 1992 fluoride poisoning in Hooper Bay, Alaska?', 'Faulty fluoridation gear', '["Contaminated drugs", "Industrial waste", "Pesticide runoff"]'::jsonb),
    ('97ee191f', 'Which lab runs the world''s largest ultra-high vacuum system?', 'CERN', '["Fermilab", "SLAC", "Brookhaven"]'::jsonb),
