    ('9f22419a', 'What is the belief that forensics gives instant answers called?', 'The CSI effect', '["The lone wolf", "The perfect witness", "The confession scene"]'::jsonb),
    ('9f2c7708', 'Which asset fuelled the housing bubble before the 2008 crash?', 'Subprime mortgages', '["Corporate bonds", "Government bonds", "Commodity futures"]'::jsonb),
    ('9fc9e8fd', 'Which studio did Tyler Perry found in Atlanta?', 'Tyler Perry Studios', '["DreamWorks Studios", "Harpo Productions", "Paramount Studios"]'::jsonb),
    ('a555d56d', 'Which Olympic venue is famous for its tent-like cable roof?', 'Munich', '["Rome", "Montreal", "Beijing"]'::jsonb),
    ('a6009235', 'Where is Marvel Studios headquartered?', 'Los Angeles', '["New York", "Atlanta", "Vancouver"]'::jsonb),
    ('a81aacd8', 'What were early Middle Eastern mosque domes mostly built from?', 'Brick', '["Wood", "Marble", "Copper"]'::jsonb),
    ('aba3f157', 'How do today''s extinction rates compare to the natural rate?', 'Much higher', '["Slightly lower", "About the same", "Not established"]'::jsonb),
    ('ada05831', 'Which process hardens the rubber soles of canvas sneakers?', 'Vulcanisation', '["Polymerisation", "Air curing", "Injection moulding"]'::jsonb),
    ('b050fb9e', 'What is the main danger of an MRI scanner''s magnetic field?', 'Flying metal objects', '["Radiation poisoning", "Acoustic trauma", "Chemical exposure"]'::jsonb),
    ('b4bc59f4', 'What is a building style tied to a historical period called?', 'An architectural era', '["A structural typology", "An urban plan", "A material index"]'::jsonb),
    ('b87ee2c6', 'Which tutorial flaw do experienced gamers complain about most?', 'It cannot be skipped', '["Too much hand-holding", "Long text screens", "Forced movement drills"]'::jsonb),
    ('ba24f42c', 'Which fast forbids water as well as food?', 'Dry fasting', '["Water fasting", "Intermittent fasting", "Lenten fasting"]'::jsonb),
    ('bba52df0', 'What is a series with a set number of episodes called?', 'Miniseries', '["Pilot", "Feature", "Sitcom"]'::jsonb),
